window.NAMES = [
  {"n": 1, "ar": "الرَّحْمَنُ", "tr": "Ar-Rahman", "en": "The Most Gracious; the Entirely Merciful", "desc": "His mercy is vast and covers all of creation in this world, believer and disbeliever alike: every breath, provision and blessing comes from it. The name is unique to Allah; no one else may be called Ar-Rahman. It opens every surah except one through the Basmalah, and Surah ar-Rahman is named after it.", "refs": ["1:1", "1:3", "17:110", "55:1", "59:22"], "benefits": [], "note": null, "theme": "mercy", "jjk": "jamal"},
  {"n": 2, "ar": "الرَّحِيمُ", "tr": "Ar-Rahim", "en": "The Most Merciful; the Especially Merciful", "desc": "Where Ar-Rahman describes the vastness of His mercy, Ar-Rahim describes its being given in particular to the believers, most fully in the Hereafter. It is a mercy that responds to faith and repentance and is constant. The Prophet ﷺ said Allah divided mercy into a hundred parts and sent down only one to the earth, keeping ninety-nine for the Day of Judgment (Bukhari 6000).", "refs": ["1:3", "2:163", "33:43", "59:22"], "benefits": [], "note": null, "theme": "mercy", "jjk": "jamal"},
  {"n": 3, "ar": "الْمَلِكُ", "tr": "Al-Malik", "en": "The King; the Sovereign", "desc": "He owns everything and rules over it with complete authority, needing no one, while all creation needs Him. Every human king is temporary and limited; His kingship is eternal and absolute. On the Day of Judgment He will fold the heavens and the earth and say: 'I am the King; where are the kings of the earth?' (Bukhari 4812).", "refs": ["20:114", "23:116", "59:23", "62:1", "114:2"], "benefits": [], "note": null, "theme": "majesty", "jjk": "jalal"},
  {"n": 4, "ar": "الْقُدُّوسُ", "tr": "Al-Quddus", "en": "The Most Holy; the Pure", "desc": "He is free of every flaw, deficiency and imperfection, and beyond anything that does not befit His majesty, including anything the mind might imagine about Him. Everything about Him, His names, attributes and actions, is pure and perfect. The angels glorify Him with 'Subbuhun Quddus' (Muslim 487).", "refs": ["59:23", "62:1"], "benefits": [], "note": null, "theme": "majesty", "jjk": "kamal"},
  {"n": 5, "ar": "السَّلَامُ", "tr": "As-Salam", "en": "The Source of Peace; the Flawless", "desc": "He is free of every defect and harm, and all peace and safety come from Him. He grants safety to His servants in this world and peace in Paradise, the 'Abode of Peace' (Dar as-Salam, 10:25). The greeting of the believers, 'as-salamu 'alaykum', is drawn from this name.", "refs": ["59:23", "10:25", "36:58"], "benefits": [{"text": "After every obligatory prayer the Prophet ﷺ would seek forgiveness three times and say: 'Allahumma antas-Salam wa minkas-salam, tabarakta ya Dhal-Jalali wal-Ikram.'", "source": "Muslim 591"}], "note": null, "theme": "mercy", "jjk": "jamal"},
  {"n": 6, "ar": "الْمُؤْمِنُ", "tr": "Al-Mu'min", "en": "The Granter of Security; the Affirmer of Truth", "desc": "He gives His creation safety from injustice, and grants His believing servants security from His punishment. He also confirms the truth of His messengers through signs and miracles, and affirms His own oneness (3:18). Whoever trusts Him is never left without protection.", "refs": ["59:23"], "benefits": [], "note": null, "theme": "guidance", "jjk": "jamal"},
  {"n": 7, "ar": "الْمُهَيْمِنُ", "tr": "Al-Muhaymin", "en": "The Guardian; the Overseer", "desc": "He watches over all of creation, sees and witnesses every deed, and preserves and governs all things. Nothing is hidden from His oversight. The Qur'an itself is described as 'muhaymin' over earlier scriptures (5:48), a guardian and criterion over them, reflecting this attribute.", "refs": ["59:23"], "benefits": [], "note": null, "theme": "guidance", "jjk": "jalal"},
  {"n": 8, "ar": "الْعَزِيزُ", "tr": "Al-'Aziz", "en": "The Almighty; the Invincible", "desc": "He is mighty and cannot be overcome, resisted or harmed. All honour and power belong to Him alone (35:10), and whoever seeks honour should seek it through obedience to Him. The name is often paired in the Qur'an with Al-Hakim, showing that His might is always exercised with wisdom.", "refs": ["2:129", "3:6", "35:10", "59:23"], "benefits": [], "note": null, "theme": "majesty", "jjk": "jalal"},
  {"n": 9, "ar": "الْجَبَّارُ", "tr": "Al-Jabbar", "en": "The Compeller; the Restorer", "desc": "He compels all things to His will, and nothing happens except as He decrees. The name also carries the meaning of 'jabr', mending what is broken: He restores the broken-hearted, enriches the poor and eases hardship. Between the two prostrations the Prophet ﷺ would ask Allah 'wajburni' (mend me) (Tirmidhi 284).", "refs": ["59:23"], "benefits": [], "note": null, "theme": "power", "jjk": "jalal"},
  {"n": 10, "ar": "الْمُتَكَبِّرُ", "tr": "Al-Mutakabbir", "en": "The Supreme in Greatness", "desc": "He alone possesses true greatness and is exalted above all creation and every flaw. Pride is His right alone and is blameworthy in any creature. In a hadith qudsi Allah says: 'Pride is My cloak and greatness My garment; whoever contends with Me over either of them, I shall cast him into the Fire' (Abu Dawud 4090; similar in Muslim 2620).", "refs": ["59:23"], "benefits": [], "note": null, "theme": "majesty", "jjk": "jalal"},
  {"n": 11, "ar": "الْخَالِقُ", "tr": "Al-Khaliq", "en": "The Creator", "desc": "He brings everything into existence from nothing, in perfect measure and according to His decree. No one else creates anything in reality. The Qur'an repeatedly asks: 'Is there any creator other than Allah?' (35:3), calling the reader to recognise that the Creator alone deserves worship.", "refs": ["6:102", "13:16", "39:62", "59:24"], "benefits": [], "note": null, "theme": "creation", "jjk": "kamal"},
  {"n": 12, "ar": "الْبَارِئُ", "tr": "Al-Bari'", "en": "The Originator; the Producer", "desc": "He brings creation into being, separating and distinguishing each thing from others and giving each its proper nature and form. Where Al-Khaliq refers to determining and creating, Al-Bari' refers to bringing it forth into existence free of disproportion. It is the second step in the sequence of 59:24.", "refs": ["2:54", "59:24"], "benefits": [], "note": null, "theme": "creation", "jjk": "kamal"},
  {"n": 13, "ar": "الْمُصَوِّرُ", "tr": "Al-Musawwir", "en": "The Fashioner of Forms", "desc": "He gives every creature its distinct shape and appearance, so that no two are alike. He shapes human beings in the wombs however He wills (3:6). This name completes the sequence Khaliq–Bari'–Musawwir: decreeing, bringing into being, then fashioning.", "refs": ["3:6", "59:24", "64:3"], "benefits": [], "note": null, "theme": "creation", "jjk": "kamal"},
  {"n": 14, "ar": "الْغَفَّارُ", "tr": "Al-Ghaffar", "en": "The Constant Forgiver", "desc": "The intensive form of the word shows that He forgives again and again, however often the servant sins and returns. He covers sins in this world and pardons them in the next. It is an open invitation never to despair of His mercy (39:53).", "refs": ["20:82", "38:66", "39:5", "71:10"], "benefits": [{"text": "Nuh (AS) told his people that seeking forgiveness from Al-Ghaffar brings abundant rain, increases wealth and children, and gives gardens and rivers.", "source": "Qur'an 71:10-12"}], "note": null, "theme": "forgiveness", "jjk": "jamal"},
  {"n": 15, "ar": "الْقَهَّارُ", "tr": "Al-Qahhar", "en": "The All-Subduer", "desc": "He has subdued all creation, and everything submits to His power and will. Even the mightiest are humbled before Him, and death subdues every living being. The name is paired in the Qur'an with Al-Wahid (13:16, 14:48), joining oneness with total dominance.", "refs": ["12:39", "13:16", "14:48", "38:65", "39:4", "40:16"], "benefits": [], "note": null, "theme": "power", "jjk": "jalal"},
  {"n": 16, "ar": "الْوَهَّابُ", "tr": "Al-Wahhab", "en": "The Bestower; the Giver of Gifts", "desc": "He gives constantly and freely, without asking for anything in return and without His treasures ever lessening. Prophets used this name when asking for great gifts: Sulayman (38:35) and the du'a of the firmly grounded in knowledge (3:8).", "refs": ["3:8", "38:9", "38:35"], "benefits": [{"text": "The Qur'anic du'a for steadfastness of the heart ends with this name: 'Rabbana la tuzigh qulubana ba'da idh hadaytana wa hab lana min ladunka rahmah, innaka antal-Wahhab.'", "source": "Qur'an 3:8"}], "note": null, "theme": "provision", "jjk": "jamal"},
  {"n": 17, "ar": "الرَّزَّاقُ", "tr": "Ar-Razzaq", "en": "The Provider", "desc": "He provides sustenance for every living creature, physical (food, wealth) and spiritual (faith, knowledge). No creature on earth lacks provision except that its provision is with Allah (11:6). Recognising this frees the heart from anxiety and from dependence on people.", "refs": ["51:58"], "benefits": [], "note": null, "theme": "provision", "jjk": "jamal"},
  {"n": 18, "ar": "الْفَتَّاحُ", "tr": "Al-Fattah", "en": "The Opener; the Judge", "desc": "He opens the doors of mercy, provision and knowledge for His servants, and opens what is closed and difficult. He also judges between people with truth, opening the way to a clear verdict (34:26). No one can hold back what He opens, nor open what He withholds (35:2).", "refs": ["7:89", "34:26"], "benefits": [], "note": null, "theme": "provision", "jjk": "jamal"},
  {"n": 19, "ar": "الْعَلِيمُ", "tr": "Al-'Alim", "en": "The All-Knowing", "desc": "His knowledge is complete and encompasses the past, present and future, the seen and unseen, the outward and the hidden thoughts of the heart. Not a leaf falls except that He knows it (6:59). It is one of the names mentioned most often in the Qur'an.", "refs": ["2:29", "2:32", "6:59", "35:38"], "benefits": [{"text": "Whoever says three times in the morning and evening 'Bismillahil-ladhi la yadurru ma'asmihi shay'un fil-ardi wa la fis-sama'i wa huwas-Sami'ul-'Alim' will not be harmed by anything.", "source": "Abu Dawud 5088; Tirmidhi 3388"}], "note": null, "theme": "knowledge", "jjk": "kamal"},
  {"n": 20, "ar": "الْقَابِضُ", "tr": "Al-Qabid", "en": "The Withholder; the Constrictor", "desc": "He restricts provision, constricts hearts or takes souls according to His wisdom. This name is always understood together with Al-Basit: He withholds and He extends, and both are from His perfect wisdom and justice. Hardship from Him is a test and a means of purification.", "refs": ["2:245"], "benefits": [], "note": "The name is derived from the verb attributed to Allah in 2:245; the name itself is established by the hadith (also Abu Dawud 3451: 'Allah is the Withholder, the Extender').", "theme": "power", "jjk": "jalal"},
  {"n": 21, "ar": "الْبَاسِطُ", "tr": "Al-Basit", "en": "The Extender; the Expander", "desc": "He extends provision generously to whom He wills and opens hearts to faith and contentment. He stretches out His hand at night to accept the repentance of those who sinned in the day, and in the day for those who sinned at night (Muslim 2759).", "refs": ["2:245", "13:26", "42:27"], "benefits": [], "note": "Derived from the verb in 2:245 and 13:26; established as a name by hadith.", "theme": "provision", "jjk": "jamal"},
  {"n": 22, "ar": "الْخَافِضُ", "tr": "Al-Khafid", "en": "The Abaser; the Lowerer", "desc": "He lowers the arrogant and the oppressors, and lowers whomever He wills by His justice. The Day of Judgment is described as 'khafidah rafi'ah', bringing some down and raising others (56:3). This name is understood together with Ar-Rafi'.", "refs": ["56:3"], "benefits": [], "note": "Not mentioned verbatim as a name in the Qur'an; 56:3 describes the Hour with this quality.", "theme": "power", "jjk": "jalal"},
  {"n": 23, "ar": "الرَّافِعُ", "tr": "Ar-Rafi'", "en": "The Exalter; the Raiser", "desc": "He raises the ranks of the believers and the people of knowledge (58:11), and raises whomever He wills in honour. He raised 'Isa (AS) to Himself (3:55) and raised the mention of the Prophet ﷺ (94:4).", "refs": ["3:55", "40:15", "58:11"], "benefits": [], "note": "Derived from the verb attributed to Allah; 40:15 calls Him 'Rafi' ad-Darajat' (Exalted in ranks).", "theme": "power", "jjk": "jamal"},
  {"n": 24, "ar": "الْمُعِزُّ", "tr": "Al-Mu'izz", "en": "The Giver of Honour", "desc": "He grants honour, strength and dignity to whom He wills. True honour comes only through obedience to Him, and whoever seeks honour elsewhere is humbled. 'You honour whom You will' (3:26).", "refs": ["3:26"], "benefits": [], "note": "Derived from the verb in 3:26; established as a name by hadith.", "theme": "power", "jjk": "jamal"},
  {"n": 25, "ar": "الْمُذِلُّ", "tr": "Al-Mudhill", "en": "The Giver of Dishonour", "desc": "He humbles and disgraces whom He wills, especially those who oppose Him and persist in arrogance. 'And You humble whom You will' (3:26). Understood with Al-Mu'izz, it teaches that honour and humiliation are in His hands alone.", "refs": ["3:26"], "benefits": [], "note": "Derived from the verb in 3:26.", "theme": "power", "jjk": "jalal"},
  {"n": 26, "ar": "السَّمِيعُ", "tr": "As-Sami'", "en": "The All-Hearing", "desc": "He hears every sound, secret and open, every language and every whispered du'a at once, without confusion. 'Nothing is like Him, and He is the All-Hearing, the All-Seeing' (42:11). Knowing this encourages heartfelt du'a and guarding the tongue.", "refs": ["2:127", "2:256", "17:1", "42:11"], "benefits": [{"text": "Whoever says three times in the morning and evening 'Bismillahil-ladhi la yadurru ma'asmihi shay'un fil-ardi wa la fis-sama'i wa huwas-Sami'ul-'Alim' will not be harmed by anything.", "source": "Abu Dawud 5088; Tirmidhi 3388"}], "note": null, "theme": "knowledge", "jjk": "kamal"},
  {"n": 27, "ar": "الْبَصِيرُ", "tr": "Al-Basir", "en": "The All-Seeing", "desc": "He sees everything, the smallest and the hidden, the black ant on a black stone on a dark night. Nothing in the heavens or earth escapes His sight. This awareness is the basis of ihsan: worshipping Allah as though you see Him, knowing that He sees you (Bukhari 50).", "refs": ["17:1", "42:11", "57:4"], "benefits": [], "note": null, "theme": "knowledge", "jjk": "kamal"},
  {"n": 28, "ar": "الْحَكَمُ", "tr": "Al-Hakam", "en": "The Judge; the Arbiter", "desc": "He judges between His servants with perfect justice in this world through His law and in the Hereafter through His verdict. His judgment cannot be overturned. 'Shall I seek a judge other than Allah?' (6:114).", "refs": ["6:114"], "benefits": [{"text": "The Prophet ﷺ changed a man's kunyah from Abu al-Hakam saying 'Allah is al-Hakam, and to Him belongs judgment.'", "source": "Abu Dawud 4955"}], "note": null, "theme": "justice", "jjk": "kamal"},
  {"n": 29, "ar": "الْعَدْلُ", "tr": "Al-'Adl", "en": "The Utterly Just", "desc": "He is justice itself and never wrongs anyone even the weight of an atom (4:40). Every decree, law and reward of His is perfectly just. He commands justice (16:90) and has forbidden injustice for Himself (Muslim 2577).", "refs": ["6:115", "16:90"], "benefits": [], "note": "Not mentioned verbatim as a name in the Qur'an; established by the hadith. 6:115 describes His word as complete 'in truth and justice'.", "theme": "justice", "jjk": "kamal"},
  {"n": 30, "ar": "اللَّطِيفُ", "tr": "Al-Latif", "en": "The Subtle; the Most Gentle", "desc": "He knows the finest, most hidden details of all things, and He is gentle and kind to His servants in ways they do not perceive. His kindness reaches them through means they never expected. Yusuf (AS) said: 'My Lord is Subtle in what He wills' (12:100).", "refs": ["6:103", "12:100", "22:63", "67:14"], "benefits": [], "note": null, "theme": "mercy", "jjk": "jamal"},
  {"n": 31, "ar": "الْخَبِيرُ", "tr": "Al-Khabir", "en": "The All-Aware", "desc": "He knows the inner reality of all things and their outcomes, the hidden intentions behind every action. His awareness covers what is in the hearts. Often paired with Al-Latif and Al-Hakim in the Qur'an.", "refs": ["6:18", "6:103", "34:1", "67:14"], "benefits": [], "note": null, "theme": "knowledge", "jjk": "kamal"},
  {"n": 32, "ar": "الْحَلِيمُ", "tr": "Al-Halim", "en": "The Forbearing", "desc": "He sees the disobedience of His servants yet does not hasten to punish them, giving them time to repent. His forbearance comes from power, not weakness. Were Allah to seize people for what they earned, He would not leave a creature on the earth (35:45).", "refs": ["2:225", "2:235", "22:59", "64:17"], "benefits": [], "note": null, "theme": "forgiveness", "jjk": "jamal"},
  {"n": 33, "ar": "الْعَظِيمُ", "tr": "Al-'Azim", "en": "The Magnificent; the Supreme", "desc": "He is great in His essence, attributes and actions beyond what the mind can grasp. Everything else is small before Him. In ruku' the believer says 'Subhana Rabbiyal-'Azim', glorifying this name in every prayer.", "refs": ["2:255", "42:4", "56:74"], "benefits": [{"text": "Two phrases are light on the tongue, heavy on the scale and beloved to Ar-Rahman: 'Subhanallahi wa bihamdihi, Subhanallahil-'Azim'.", "source": "Bukhari 6406; Muslim 2694"}], "note": null, "theme": "majesty", "jjk": "jalal"},
  {"n": 34, "ar": "الْغَفُورُ", "tr": "Al-Ghafur", "en": "The All-Forgiving", "desc": "He forgives sins completely, however great, and covers them so they are not exposed. Where Al-Ghaffar stresses repetition, Al-Ghafur stresses the greatness of the forgiveness itself. 'Do not despair of the mercy of Allah; He forgives all sins' (39:53).", "refs": ["2:173", "15:49", "39:53"], "benefits": [], "note": null, "theme": "forgiveness", "jjk": "jamal"},
  {"n": 35, "ar": "الشَّكُورُ", "tr": "Ash-Shakur", "en": "The Most Appreciative", "desc": "He rewards small deeds with great reward, multiplies good deeds and does not let any good effort go to waste. He appreciates even a little sincerity, as when He forgave a man for removing a thorny branch from the road (Bukhari 652).", "refs": ["35:30", "35:34", "64:17"], "benefits": [], "note": null, "theme": "mercy", "jjk": "jamal"},
  {"n": 36, "ar": "الْعَلِيُّ", "tr": "Al-'Aliyy", "en": "The Most High", "desc": "He is high above all creation in His essence, status and power. Nothing is above Him. In sujud, the lowest position of the body, the believer says 'Subhana Rabbiyal-A'la', glorifying His highness.", "refs": ["2:255", "4:34", "22:62", "42:4"], "benefits": [], "note": null, "theme": "majesty", "jjk": "kamal"},
  {"n": 37, "ar": "الْكَبِيرُ", "tr": "Al-Kabir", "en": "The Most Great", "desc": "He is greater than everything, and nothing compares to His greatness. 'Allahu Akbar' is repeated throughout the adhan and prayer to remind the believer that Allah is greater than any worldly concern.", "refs": ["13:9", "22:62", "31:30", "34:23"], "benefits": [], "note": null, "theme": "majesty", "jjk": "jalal"},
  {"n": 38, "ar": "الْحَفِيظُ", "tr": "Al-Hafiz", "en": "The Preserver; the Protector", "desc": "He preserves the heavens and earth from collapsing, records all deeds, and protects His servants from harm. He preserved the Qur'an from alteration (15:9). 'Allah is the best guardian' (12:64).", "refs": ["11:57", "12:64", "34:21"], "benefits": [{"text": "The Prophet ﷺ advised Ibn 'Abbas: 'Guard (the limits of) Allah and He will guard you.'", "source": "Tirmidhi 2516"}], "note": null, "theme": "guidance", "jjk": "jamal"},
  {"n": 39, "ar": "الْمُقِيتُ", "tr": "Al-Muqit", "en": "The Sustainer; the Nourisher", "desc": "He provides every creature with the nourishment it needs, physical and spiritual, and He has power over all things and watches over them. He determined the sustenance of the earth in four days (41:10).", "refs": ["4:85"], "benefits": [], "note": null, "theme": "provision", "jjk": "jamal"},
  {"n": 40, "ar": "الْحَسِيبُ", "tr": "Al-Hasib", "en": "The Reckoner; the Sufficient", "desc": "He takes account of every deed of His servants and will reckon them precisely. He is also sufficient for whoever relies on Him: 'Whoever puts his trust in Allah, He is sufficient for him' (65:3).", "refs": ["4:6", "4:86", "33:39"], "benefits": [], "note": null, "theme": "justice", "jjk": "kamal"},
  {"n": 41, "ar": "الْجَلِيلُ", "tr": "Al-Jalil", "en": "The Majestic", "desc": "He possesses majesty in His attributes, greatness and beauty. Hearts are filled with awe and reverence before Him. The name is closely related to 'Dhul-Jalal', the Lord of Majesty (55:27).", "refs": ["55:27", "55:78"], "benefits": [], "note": "Not mentioned verbatim in the Qur'an; related to 'Dhul-Jalal' in 55:27 and 55:78.", "theme": "majesty", "jjk": "jalal"},
  {"n": 42, "ar": "الْكَرِيمُ", "tr": "Al-Karim", "en": "The Most Generous; the Noble", "desc": "He gives without being asked, gives more than is hoped for, and forgives with grace. 'O mankind, what has deceived you concerning your Lord, the Generous?' (82:6). Allah is shy to turn away empty the hands of a servant raised to Him (Abu Dawud 1488).", "refs": ["23:116", "27:40", "82:6"], "benefits": [], "note": null, "theme": "provision", "jjk": "jamal"},
  {"n": 43, "ar": "الرَّقِيبُ", "tr": "Ar-Raqib", "en": "The Watchful", "desc": "He watches over His servants at all times and nothing escapes Him. Awareness of this (muraqabah) is a foundation of taqwa: being mindful of Allah in private as in public.", "refs": ["4:1", "5:117", "33:52"], "benefits": [], "note": null, "theme": "guidance", "jjk": "kamal"},
  {"n": 44, "ar": "الْمُجِيبُ", "tr": "Al-Mujib", "en": "The Responsive; the Answerer of Prayer", "desc": "He answers the du'a of those who call upon Him, and responds to the distressed. 'My Lord is near and responsive' (11:61). 'When My servants ask you concerning Me, I am near; I respond to the call of the caller' (2:186).", "refs": ["2:186", "11:61"], "benefits": [{"text": "A du'a is answered in one of three ways: it is granted, a harm is averted, or a reward is stored for the Hereafter.", "source": "Ahmad 11133"}], "note": null, "theme": "mercy", "jjk": "jamal"},
  {"n": 45, "ar": "الْوَاسِعُ", "tr": "Al-Wasi'", "en": "The All-Encompassing; the Boundless", "desc": "His knowledge, mercy, generosity and power are vast and encompass all things. 'My mercy encompasses all things' (7:156). There is no limit to what He can give.", "refs": ["2:115", "2:247", "2:268", "7:156"], "benefits": [], "note": null, "theme": "provision", "jjk": "jamal"},
  {"n": 46, "ar": "الْحَكِيمُ", "tr": "Al-Hakim", "en": "The All-Wise", "desc": "Everything He creates, commands and decrees is placed exactly where it belongs and has a purpose, even when people do not understand it. His wisdom is behind every hardship and ease. One of the most frequent names in the Qur'an.", "refs": ["2:32", "2:129", "59:24", "66:2"], "benefits": [], "note": null, "theme": "knowledge", "jjk": "kamal"},
  {"n": 47, "ar": "الْوَدُودُ", "tr": "Al-Wadud", "en": "The Most Loving", "desc": "He loves His righteous servants and is beloved by them. When Allah loves a servant, He calls Jibril, and love for him is placed in the hearts of the people of heaven and earth (Bukhari 3209). 'He is the Forgiving, the Loving' (85:14).", "refs": ["11:90", "85:14"], "benefits": [], "note": null, "theme": "mercy", "jjk": "jamal"},
  {"n": 48, "ar": "الْمَجِيدُ", "tr": "Al-Majid", "en": "The Most Glorious", "desc": "He is glorious in His essence, honour and generosity, and His glory is vast. The name appears at the end of the Durood Ibrahimi: 'innaka Hamidun Majid'.", "refs": ["11:73", "85:15"], "benefits": [], "note": null, "theme": "majesty", "jjk": "jamal"},
  {"n": 49, "ar": "الْبَاعِثُ", "tr": "Al-Ba'ith", "en": "The Resurrector", "desc": "He will raise the dead from their graves on the Day of Judgment, and He sent messengers to mankind. 'Allah will resurrect those in the graves' (22:7).", "refs": ["22:7", "58:6"], "benefits": [], "note": "Derived from the verb attributed to Allah in these verses.", "theme": "creation", "jjk": "jalal"},
  {"n": 50, "ar": "الشَّهِيدُ", "tr": "Ash-Shahid", "en": "The Witness", "desc": "He is present and witnesses everything; nothing is absent from Him. He will bear witness on the Day of Judgment. 'Is it not sufficient that your Lord is witness over all things?' (41:53).", "refs": ["4:79", "22:17", "33:55", "41:53"], "benefits": [], "note": null, "theme": "knowledge", "jjk": "kamal"},
  {"n": 51, "ar": "الْحَقُّ", "tr": "Al-Haqq", "en": "The Truth; the Real", "desc": "His existence is the only necessary, everlasting reality; everything else depends on Him. His word, promise and meeting are true. The Prophet ﷺ would say in night prayer: 'You are the Truth, Your promise is true…' (Bukhari 1120).", "refs": ["20:114", "22:6", "22:62", "24:25"], "benefits": [], "note": null, "theme": "oneness", "jjk": "kamal"},
  {"n": 52, "ar": "الْوَكِيلُ", "tr": "Al-Wakil", "en": "The Trustee; the Disposer of Affairs", "desc": "He takes charge of the affairs of those who rely on Him and is sufficient for them. True tawakkul is to do one's part and then entrust the outcome to Him.", "refs": ["3:173", "4:81", "73:9"], "benefits": [{"text": "'Hasbunallahu wa ni'mal-Wakil' was said by Ibrahim (AS) when thrown into the fire, and by the Prophet ﷺ when told the enemy had gathered against him.", "source": "Bukhari 4563; Qur'an 3:173-174"}], "note": null, "theme": "guidance", "jjk": "jamal"},
  {"n": 53, "ar": "الْقَوِيُّ", "tr": "Al-Qawiyy", "en": "The All-Strong", "desc": "His strength is complete and never weakens or tires. He is never overcome. 'Indeed, Allah is Strong and Mighty' (22:40).", "refs": ["22:40", "22:74", "42:19", "57:25"], "benefits": [], "note": null, "theme": "power", "jjk": "jalal"},
  {"n": 54, "ar": "الْمَتِينُ", "tr": "Al-Matin", "en": "The Firm; the Steadfast", "desc": "His power is firm and enduring, and He never needs help or rest. 'Indeed, Allah is the Provider, the Possessor of strength, the Firm' (51:58).", "refs": ["51:58"], "benefits": [], "note": null, "theme": "power", "jjk": "jalal"},
  {"n": 55, "ar": "الْوَلِيُّ", "tr": "Al-Waliyy", "en": "The Protecting Friend", "desc": "He is the ally and helper of the believers, bringing them out of darkness into light (2:257). Whoever takes Allah as his protector is never truly alone.", "refs": ["2:257", "4:45", "42:9", "42:28"], "benefits": [], "note": null, "theme": "guidance", "jjk": "jamal"},
  {"n": 56, "ar": "الْحَمِيدُ", "tr": "Al-Hamid", "en": "The Praiseworthy", "desc": "He is worthy of all praise in every state, for His perfect attributes and countless blessings, whether or not people praise Him. 'Allah is Free of need, the Praiseworthy' (35:15).", "refs": ["14:8", "31:12", "35:15"], "benefits": [], "note": null, "theme": "mercy", "jjk": "kamal"},
  {"n": 57, "ar": "الْمُحْصِي", "tr": "Al-Muhsi", "en": "The Accounter; the Reckoner of All", "desc": "He has counted and recorded everything precisely: every creature, breath, drop of rain and deed. 'He has enumerated everything in number' (72:28).", "refs": ["19:94", "72:28"], "benefits": [], "note": "Derived from the verb attributed to Allah in these verses.", "theme": "knowledge", "jjk": "kamal"},
  {"n": 58, "ar": "الْمُبْدِئُ", "tr": "Al-Mubdi'", "en": "The Originator", "desc": "He began creation the first time without any prior example. 'It is He who originates and repeats' (85:13).", "refs": ["10:4", "85:13"], "benefits": [], "note": "Derived from the verb attributed to Allah in these verses.", "theme": "creation", "jjk": "kamal"},
  {"n": 59, "ar": "الْمُعِيدُ", "tr": "Al-Mu'id", "en": "The Restorer", "desc": "He will bring creation back after death, and that is easier for Him (30:27). The one who began creation can surely restore it.", "refs": ["30:27", "85:13"], "benefits": [], "note": "Derived from the verb attributed to Allah in these verses.", "theme": "creation", "jjk": "kamal"},
  {"n": 60, "ar": "الْمُحْيِي", "tr": "Al-Muhyi", "en": "The Giver of Life", "desc": "He gives life to the dead, to the barren earth with rain, and to dead hearts with faith. 'Indeed, He who gave it life is the Giver of life to the dead' (41:39).", "refs": ["30:50", "41:39"], "benefits": [], "note": null, "theme": "creation", "jjk": "jamal"},
  {"n": 61, "ar": "الْمُمِيتُ", "tr": "Al-Mumit", "en": "The Bringer of Death", "desc": "He decrees death for every living being at its appointed time; no one dies except by His permission (3:145). Remembering this brings sincerity and readiness for the Hereafter.", "refs": ["15:23", "57:2"], "benefits": [], "note": "Derived from the verb attributed to Allah in these verses.", "theme": "creation", "jjk": "jalal"},
  {"n": 62, "ar": "الْحَيُّ", "tr": "Al-Hayy", "en": "The Ever-Living", "desc": "His life is perfect, without beginning or end, and is not touched by sleep or weariness. Every other life comes from Him and depends on Him. 'Rely upon the Ever-Living who does not die' (25:58).", "refs": ["2:255", "3:2", "20:111", "25:58"], "benefits": [{"text": "Ayat al-Kursi (2:255), which opens with 'Al-Hayyul-Qayyum', is the greatest verse in the Qur'an.", "source": "Muslim 810"}, {"text": "In distress the Prophet ﷺ would say: 'Ya Hayyu ya Qayyum, bi rahmatika astaghith'.", "source": "Tirmidhi 3524"}], "note": null, "theme": "oneness", "jjk": "kamal"},
  {"n": 63, "ar": "الْقَيُّومُ", "tr": "Al-Qayyum", "en": "The Self-Subsisting Sustainer", "desc": "He exists by Himself, needing no one, and sustains everything else. The heavens, earth and all creation stand by His command. Paired with Al-Hayy, it is said by some scholars to be the Greatest Name.", "refs": ["2:255", "3:2", "20:111"], "benefits": [{"text": "Ayat al-Kursi, containing 'Al-Hayyul-Qayyum', is the greatest verse in the Qur'an.", "source": "Muslim 810"}, {"text": "The Greatest Name of Allah, by which du'a is answered, is in three surahs: al-Baqarah, Al 'Imran and Ta-Ha (where 'Al-Hayyul-Qayyum' appears).", "source": "Ibn Majah 3856"}], "note": null, "theme": "oneness", "jjk": "kamal"},
  {"n": 64, "ar": "الْوَاجِدُ", "tr": "Al-Wajid", "en": "The Finder; the Self-Sufficient", "desc": "He finds whatever He wills and lacks nothing. Nothing is lost to Him and nothing escapes Him. He found the Prophet ﷺ an orphan and sheltered him, and found him in need and enriched him (93:6-8).", "refs": ["93:6-8"], "benefits": [], "note": "Not in the Qur'an as a name; established by the hadith. The verb appears in 93:6-8.", "theme": "provision", "jjk": "kamal"},
  {"n": 65, "ar": "الْمَاجِدُ", "tr": "Al-Majid (Al-Maajid)", "en": "The Illustrious; the Noble", "desc": "He possesses noble, abundant glory and generosity. It is close in meaning to Al-Majeed, with emphasis on the abundance of His generosity.", "refs": ["11:73"], "benefits": [], "note": "Not verbatim in the Qur'an; related to Al-Majeed (11:73).", "theme": "majesty", "jjk": "jamal"},
  {"n": 66, "ar": "الْوَاحِدُ", "tr": "Al-Wahid", "en": "The One", "desc": "He is one in His essence, attributes and actions, with no partner, rival or equal. This oneness (tawhid) is the foundation of Islam.", "refs": ["2:163", "13:16", "14:48", "38:65"], "benefits": [], "note": null, "theme": "oneness", "jjk": "kamal"},
  {"n": 67, "ar": "الْأَحَدُ", "tr": "Al-Ahad", "en": "The Unique; the Only One", "desc": "He is unique and indivisible, with nothing like Him in any way. 'Say: He is Allah, the One' (112:1). Bilal (RA) repeated 'Ahad, Ahad' while tortured.", "refs": ["112:1"], "benefits": [{"text": "Surah al-Ikhlas, which begins with this name, is equal to a third of the Qur'an.", "source": "Bukhari 5013"}, {"text": "The Prophet ﷺ heard a man calling on Allah as 'al-Ahad as-Samad' and said he had asked by the Greatest Name.", "source": "Abu Dawud 1493; Tirmidhi 3475"}], "note": null, "theme": "oneness", "jjk": "kamal"},
  {"n": 68, "ar": "الصَّمَدُ", "tr": "As-Samad", "en": "The Eternal Refuge", "desc": "He is the Master to whom all creation turns in every need, while He needs no one. He neither eats nor drinks, is perfect in His attributes, and does not perish.", "refs": ["112:2"], "benefits": [{"text": "Surah al-Ikhlas, which contains this name, is equal to a third of the Qur'an.", "source": "Bukhari 5013"}], "note": null, "theme": "oneness", "jjk": "kamal"},
  {"n": 69, "ar": "الْقَادِرُ", "tr": "Al-Qadir", "en": "The All-Capable", "desc": "He is able to do anything He wills, and nothing is impossible for Him. He is able to send punishment, and able to resurrect the dead (75:40).", "refs": ["6:65", "17:99", "36:81", "75:40"], "benefits": [], "note": null, "theme": "power", "jjk": "jalal"},
  {"n": 70, "ar": "الْمُقْتَدِرُ", "tr": "Al-Muqtadir", "en": "The All-Determining; the Powerful", "desc": "An intensive form of Al-Qadir: His power is perfect, carried out fully, and He determines all things. 'In a seat of truth near a Sovereign, Perfect in Ability' (54:55).", "refs": ["18:45", "54:42", "54:55"], "benefits": [], "note": null, "theme": "power", "jjk": "jalal"},
  {"n": 71, "ar": "الْمُقَدِّمُ", "tr": "Al-Muqaddim", "en": "The Expediter; the One Who Brings Forward", "desc": "He brings forward whom He wills and what He wills, in time, rank and honour, according to His wisdom. The Prophet ﷺ said in du'a: 'Antal-Muqaddimu wa antal-Mu'akhkhir' (Bukhari 1120).", "refs": ["50:28"], "benefits": [], "note": "Not in the Qur'an as a name; established by authentic hadith (Bukhari 1120).", "theme": "power", "jjk": "jalal"},
  {"n": 72, "ar": "الْمُؤَخِّرُ", "tr": "Al-Mu'akhkhir", "en": "The Delayer", "desc": "He delays what He wills, the punishment of sinners to give them time to repent, and matters until their right time. 'Allah defers them for an appointed term' (14:42).", "refs": ["14:42", "71:4"], "benefits": [], "note": "Not in the Qur'an as a name; established by authentic hadith (Bukhari 1120).", "theme": "power", "jjk": "jalal"},
  {"n": 73, "ar": "الْأَوَّلُ", "tr": "Al-Awwal", "en": "The First", "desc": "He existed before everything, with no beginning. The Prophet ﷺ explained: 'You are the First, there is nothing before You' (Muslim 2713).", "refs": ["57:3"], "benefits": [], "note": null, "theme": "oneness", "jjk": "kamal"},
  {"n": 74, "ar": "الْآخِرُ", "tr": "Al-Akhir", "en": "The Last", "desc": "He remains after everything perishes, with no end. 'You are the Last, there is nothing after You' (Muslim 2713).", "refs": ["57:3"], "benefits": [], "note": null, "theme": "oneness", "jjk": "kamal"},
  {"n": 75, "ar": "الظَّاهِرُ", "tr": "Az-Zahir", "en": "The Manifest", "desc": "He is above everything, and His existence is evident through the signs of creation. 'You are the Manifest, there is nothing above You' (Muslim 2713).", "refs": ["57:3"], "benefits": [], "note": null, "theme": "knowledge", "jjk": "kamal"},
  {"n": 76, "ar": "الْبَاطِنُ", "tr": "Al-Batin", "en": "The Hidden; the Inward", "desc": "He is hidden from physical sight in this world, yet nearer to everything than anything else, and knows all inner matters. 'You are the Hidden, there is nothing closer than You' (Muslim 2713).", "refs": ["57:3"], "benefits": [{"text": "The du'a containing these four names (Al-Awwal, Al-Akhir, Az-Zahir, Al-Batin) was taught by the Prophet ﷺ to be said at bedtime, ending '…settle our debt and enrich us from poverty'.", "source": "Muslim 2713"}], "note": null, "theme": "knowledge", "jjk": "kamal"},
  {"n": 77, "ar": "الْوَالِي", "tr": "Al-Wali", "en": "The Governor; the Patron", "desc": "He governs all affairs of creation and manages them. 'For them besides Him there is no patron' (13:11).", "refs": ["13:11"], "benefits": [], "note": null, "theme": "majesty", "jjk": "jalal"},
  {"n": 78, "ar": "الْمُتَعَالِي", "tr": "Al-Muta'ali", "en": "The Supremely Exalted", "desc": "He is far above anything that does not befit Him and exalted above all creation. 'Knower of the unseen and the witnessed, the Grand, the Exalted' (13:9).", "refs": ["13:9"], "benefits": [], "note": null, "theme": "majesty", "jjk": "jalal"},
  {"n": 79, "ar": "الْبَرُّ", "tr": "Al-Barr", "en": "The Source of All Goodness", "desc": "He is kind and gracious to His servants, does good to them, and is true to His promise. 'Indeed, it is He who is the Beneficent, the Merciful' (52:28).", "refs": ["52:28"], "benefits": [], "note": null, "theme": "mercy", "jjk": "jamal"},
  {"n": 80, "ar": "التَّوَّابُ", "tr": "At-Tawwab", "en": "The Ever-Accepting of Repentance", "desc": "He guides servants to repent and accepts their repentance again and again. He turned to Adam (AS) after his slip (2:37). Allah rejoices at the repentance of His servant more than a man who finds his lost camel in the desert (Muslim 2747).", "refs": ["2:37", "2:128", "49:12", "110:3"], "benefits": [{"text": "The Prophet ﷺ would say a hundred times in one sitting: 'Rabbighfir li wa tub 'alayya, innaka antat-Tawwabur-Rahim'.", "source": "Abu Dawud 1516; Tirmidhi 3434"}], "note": null, "theme": "forgiveness", "jjk": "jamal"},
  {"n": 81, "ar": "الْمُنْتَقِمُ", "tr": "Al-Muntaqim", "en": "The Avenger", "desc": "He brings just retribution on those who persist in wrongdoing and oppression after being warned. It is never injustice, but the consequence of their own choices.", "refs": ["3:4", "32:22", "43:41"], "benefits": [], "note": "In the Qur'an as 'Dhu Intiqam' (3:4) and 'muntaqimun' (32:22).", "theme": "justice", "jjk": "jalal"},
  {"n": 82, "ar": "الْعَفُوُّ", "tr": "Al-'Afuww", "en": "The Pardoner", "desc": "He erases sins completely, as if they never existed, which goes beyond covering them. 'Allah is ever Pardoning and Forgiving' (4:43).", "refs": ["4:43", "4:99", "22:60", "58:2"], "benefits": [{"text": "For Laylat al-Qadr the Prophet ﷺ taught 'A'ishah (RA): 'Allahumma innaka 'Afuwwun tuhibbul-'afwa fa'fu 'anni'.", "source": "Tirmidhi 3513"}], "note": null, "theme": "forgiveness", "jjk": "jamal"},
  {"n": 83, "ar": "الرَّءُوفُ", "tr": "Ar-Ra'uf", "en": "The Most Kind; the Compassionate", "desc": "His compassion is intense and tender, a gentleness that removes hardship. 'Indeed, Allah is to the people Kind and Merciful' (2:143).", "refs": ["2:143", "9:117", "57:9"], "benefits": [], "note": null, "theme": "mercy", "jjk": "jamal"},
  {"n": 84, "ar": "مَالِكُ الْمُلْكِ", "tr": "Malik al-Mulk", "en": "The Owner of All Sovereignty", "desc": "He owns all dominion, gives it to whom He wills and takes it from whom He wills (3:26). Every worldly authority is lent by Him.", "refs": ["3:26"], "benefits": [], "note": null, "theme": "majesty", "jjk": "jalal"},
  {"n": 85, "ar": "ذُو الْجَلَالِ وَالْإِكْرَامِ", "tr": "Dhul-Jalali wal-Ikram", "en": "Lord of Majesty and Generosity", "desc": "He possesses majesty that deserves reverence, and generosity that He bestows on His servants. Everything will perish except His Face, Lord of Majesty and Honour (55:27).", "refs": ["55:27", "55:78"], "benefits": [{"text": "The Prophet ﷺ said: 'Persist in saying: Ya Dhal-Jalali wal-Ikram.'", "source": "Tirmidhi 3525"}, {"text": "It is part of the dhikr after every obligatory prayer: '…tabarakta ya Dhal-Jalali wal-Ikram.'", "source": "Muslim 591"}], "note": null, "theme": "majesty", "jjk": "kamal"},
  {"n": 86, "ar": "الْمُقْسِطُ", "tr": "Al-Muqsit", "en": "The Equitable", "desc": "He establishes justice and gives every right to its owner. He loves those who act justly (49:9). The just will be on pulpits of light at the right hand of Ar-Rahman (Muslim 1827).", "refs": ["3:18", "21:47"], "benefits": [], "note": "Not verbatim as a name; 3:18 describes Him as 'maintaining justice (qist)'.", "theme": "justice", "jjk": "kamal"},
  {"n": 87, "ar": "الْجَامِعُ", "tr": "Al-Jami'", "en": "The Gatherer", "desc": "He will gather all mankind on the Day of Judgment, and gathers opposites in creation. 'Our Lord, You will gather the people for a Day about which there is no doubt' (3:9).", "refs": ["3:9", "4:140"], "benefits": [], "note": null, "theme": "creation", "jjk": "kamal"},
  {"n": 88, "ar": "الْغَنِيُّ", "tr": "Al-Ghaniyy", "en": "The Self-Sufficient; the Rich", "desc": "He is free of all needs, while all creation is in need of Him. Worship benefits the servant, not Allah. 'O mankind, you are the ones in need of Allah, and Allah is Free of need' (35:15).", "refs": ["2:263", "35:15", "39:7"], "benefits": [], "note": null, "theme": "provision", "jjk": "kamal"},
  {"n": 89, "ar": "الْمُغْنِي", "tr": "Al-Mughni", "en": "The Enricher", "desc": "He enriches whom He wills with wealth, and enriches hearts with contentment. True richness is richness of the soul (Bukhari 6446).", "refs": ["9:28", "53:48"], "benefits": [], "note": "Derived from the verb attributed to Allah in these verses.", "theme": "provision", "jjk": "jamal"},
  {"n": 90, "ar": "الْمَانِعُ", "tr": "Al-Mani'", "en": "The Preventer; the Withholder", "desc": "He prevents harm from His servants and withholds what He wills by His wisdom. 'O Allah, none can withhold what You give, and none can give what You withhold' (Bukhari 844).", "refs": ["35:2"], "benefits": [], "note": "Not in the Qur'an as a name; meaning reflected in 35:2.", "theme": "power", "jjk": "jalal"},
  {"n": 91, "ar": "الضَّارُّ", "tr": "Ad-Darr", "en": "The Distresser", "desc": "No harm reaches anyone except by His permission and wisdom. Understood only together with An-Nafi': harm and benefit are both in His hands. 'If Allah touches you with harm, none can remove it but Him' (6:17).", "refs": ["6:17", "10:107"], "benefits": [], "note": "Not in the Qur'an as a name; meaning from 6:17 and 10:107. Scholars stress it be mentioned only paired with An-Nafi'.", "theme": "power", "jjk": "jalal"},
  {"n": 92, "ar": "النَّافِعُ", "tr": "An-Nafi'", "en": "The Benefactor", "desc": "All benefit comes from Him. Even if the whole nation gathered to benefit you, they could do so only with what Allah has written for you (Tirmidhi 2516).", "refs": ["10:107", "48:11"], "benefits": [], "note": "Not in the Qur'an as a name; meaning from 10:107 and 48:11.", "theme": "power", "jjk": "jamal"},
  {"n": 93, "ar": "النُّورُ", "tr": "An-Nur", "en": "The Light", "desc": "He is the Light of the heavens and the earth (24:35): He illuminates creation, and the hearts of believers through guidance. His veil is light (Muslim 179).", "refs": ["24:35"], "benefits": [], "note": null, "theme": "guidance", "jjk": "jamal"},
  {"n": 94, "ar": "الْهَادِي", "tr": "Al-Hadi", "en": "The Guide", "desc": "He guides creatures to what benefits them, and guides hearts to faith. 'Your Lord is sufficient as a Guide and Helper' (25:31). Every Muslim asks for guidance in each rak'ah: 'Ihdinas-siratal-mustaqim'.", "refs": ["22:54", "25:31"], "benefits": [], "note": null, "theme": "guidance", "jjk": "jamal"},
  {"n": 95, "ar": "الْبَدِيعُ", "tr": "Al-Badi'", "en": "The Incomparable Originator", "desc": "He created the heavens and earth with no previous model, in wondrous perfection. 'Originator of the heavens and the earth' (2:117).", "refs": ["2:117", "6:101"], "benefits": [], "note": null, "theme": "creation", "jjk": "kamal"},
  {"n": 96, "ar": "الْبَاقِي", "tr": "Al-Baqi", "en": "The Everlasting", "desc": "He remains forever while everything else perishes. 'Everyone on the earth will perish, and the Face of your Lord will remain' (55:26-27).", "refs": ["20:73", "55:27"], "benefits": [], "note": "Derived from 55:27 ('yabqa').", "theme": "oneness", "jjk": "kamal"},
  {"n": 97, "ar": "الْوَارِثُ", "tr": "Al-Warith", "en": "The Inheritor", "desc": "He remains after all creation passes and inherits everything; all ownership returns to Him. 'We are the Inheritors' (15:23). Zakariyya (AS) called Him 'the best of inheritors' (21:89).", "refs": ["15:23", "19:40", "21:89"], "benefits": [], "note": null, "theme": "oneness", "jjk": "kamal"},
  {"n": 98, "ar": "الرَّشِيدُ", "tr": "Ar-Rashid", "en": "The Guide to the Right Path", "desc": "All His actions and decrees are rightly directed, and He guides His servants to what is right. The youths of the cave prayed: 'Prepare for us right guidance (rashada)' (18:10).", "refs": ["18:10", "72:10"], "benefits": [], "note": "Not in the Qur'an as a name; related to 'rashad' (right guidance).", "theme": "guidance", "jjk": "jamal"},
  {"n": 99, "ar": "الصَّبُورُ", "tr": "As-Sabur", "en": "The Most Patient", "desc": "He does not hasten punishment despite the disobedience of His creation, giving them time. The Prophet ﷺ said: 'No one is more patient upon hurtful words than Allah: they ascribe a son to Him, yet He gives them health and provision' (Bukhari 6099).", "refs": [], "benefits": [], "note": "Not in the Qur'an as a name; established by hadith (Bukhari 6099).", "theme": "forgiveness", "jjk": "jamal"}
];
